import (
	"fmt"
	"strings"
)

func render(md string) string {
	var out strings.Builder
	for _, ln := range strings.Split(md, "\n") {
		switch {
		case strings.HasPrefix(ln, "# "):
			fmt.Fprintf(&out, "<h1>%s</h1>\n", strings.TrimPrefix(ln, "# "))
		case strings.HasPrefix(ln, "- "):
			fmt.Fprintf(&out, "<li>%s</li>\n", strings.TrimPrefix(ln, "- "))
		default:
			fmt.Fprintf(&out, "<p>%s</p>\n", ln)
		}
	}
	return out.String()
}

func main() {
	fmt.Print(render("# Hi\n- a\n- b\nbye"))
}

