import (
	"fmt"
	"sync"
	"time"
)

func fetch(name string, ms int, words int, wg *sync.WaitGroup, out []string, i int) {
	defer wg.Done()
	time.Sleep(time.Duration(ms) * time.Millisecond)
	out[i] = fmt.Sprintf("%s: %d words", name, words)
}

func main() {
	names := []string{"blog", "docs", "news"}
	lats := []int{30, 10, 20}
	counts := []int{120, 340, 210}
	out := make([]string, 3)
	var wg sync.WaitGroup
	wg.Add(3)
	for i := range names {
		go fetch(names[i], lats[i], counts[i], &wg, out, i)
	}
	for _, line := range out {
		fmt.Println(line)
	}
	fmt.Println("Fetched 3 pages!")
}

