import "fmt"

func main() {
	qs := []string{"Go mascot?", "go run does what?", "Slice length of []int{1,2,3}?"}
	keys := []string{"gopher", "compile and run", "3"}
	got := []string{"gopher", "compile only", "3"}
	score := 0
	for i := range qs {
		fmt.Println("Q:", qs[i])
		if got[i] == keys[i] {
			fmt.Println("Correct!")
			score++
		} else {
			fmt.Println("Wrong — it was", keys[i])
		}
	}
	fmt.Println("Score:", score, "/", len(qs))
}

